mapper.select:
select count(distinct problem_id)
from submit_log
where user_id = #{userId}

select date_format(submit_time, '%Y-%m-%d') as date, count(*) as count
from submit_log
where user_id = #{userId}
  and submit_time >= #{startTime}
  and submit_time < #{endTime}
group by date_format(submit_time, '%Y-%m-%d')
order by date
limit 366
